  world.emit?.('dungeon:transitioned', {
    depth: newDepth,
    templateId: newTemplateId || "",
    regionKey: restoredRegionKey,
    anchor: { x: Number(newRegionAnchorX || 0) | 0, y: Number(newRegionAnchorY || 0) | 0 },
    profileType: newProfileType || "default",
    pos: destinationPos,
